b:includable.script:
//
(function(){
 var original="https://catonpe-droid.github.io/lokhit-maharashtra/";
 var originalTitles={};
 var pageTitles={"about":"About Us","contact":"Contact Us","advertise":"Advertising & Partnerships","privacy-policy":"Privacy Policy","terms":"Terms & Conditions","disclaimer":"Disclaimer","grievance":"Grievance Redressal","cookie-policy":"Cookie Policy","editorial-policy":"Editorial Policy","corrections":"Corrections Policy","live-tv":"YouTube Live TV | लोकहित महाराष्ट्र","video":"व्हिडिओ बातम्या"};
 function pathOf(a){try{return new URL(a.href).pathname;}catch(e){return '';}}
 function run(){
  fetch('/feeds/posts/default?alt=json&max-results=500',{credentials:'same-origin'}).then(function(r){if(!r.ok)throw Error('feed not available');return r.json()}).then(function(result){
   var entries=(result.feed&&result.feed.entry)||[], links={};
   entries.forEach(function(e){var title=e.title&&e.title.$t||'',l=(e.link||[]).find(function(x){return x.rel==='alternate'&&x.type==='text/html'});if(l)links[title]=l.href;});
   document.querySelectorAll('a[href]').forEach(function(a){var after=pathOf(a).split('/batmi/')[1];if(!after)return;var slug=decodeURIComponent(after.split('/')[0]);if(originalTitles[slug]&&links[originalTitles[slug]])a.href=links[originalTitles[slug]];});
   var grid=document.getElementById('homepage-latest-grid'),known=new Set(Object.values(originalTitles));
   if(!grid)return;
   entries.slice().reverse().forEach(function(e){
    var title=e.title&&e.title.$t||'';if(!title||known.has(title)||!links[title])return;
    var a=document.createElement('a');a.className='news-card';a.href=links[title];
    var img=document.createElement('img');img.loading='lazy';img.alt=title;
    var markup=e.content&&e.content.$t||'',found=markup.match(/<img[^>]+src=["']([^"']+)/i);
    img.src=(e.media$thumbnail&&e.media$thumbnail.url)||(found&&found[1])||original+'assets/img/logo.webp';
    var box=document.createElement('div');box.className='card-body';
    var tag=document.createElement('span');tag.className='category-kicker';
    var label=(e.category||[]).find(function(c){return c.scheme==='http://www.blogger.com/atom/ns#';});
    tag.textContent=label&&label.term||'ताज्या बातम्या';
    var h=document.createElement('h3');h.textContent=title;
    var p=document.createElement('p');p.textContent=(e.summary&&e.summary.$t||'').replace(/<[^>]*>/g,'').slice(0,155);
    box.append(tag,h,p);a.append(img,box);grid.prepend(a);
   });
  }).catch(function(e){console.warn('Lokhit feed sync disabled:',e);});
  fetch('/feeds/pages/default?alt=json&max-results=100',{credentials:'same-origin'}).then(function(r){if(!r.ok)throw Error('pages feed not available');return r.json()}).then(function(data){
   var pages=(data.feed&&data.feed.entry)||[],links={};
   pages.forEach(function(e){var l=(e.link||[]).find(function(a){return a.rel==='alternate'&&a.type==='text/html'});if(l)links[e.title&&e.title.$t||'']=l.href;});
   document.querySelectorAll('a[href]').forEach(function(a){var path=pathOf(a),slug=path.split('/lokhit-maharashtra/')[1];if(!slug)return;slug=slug.split('/')[0];if(pageTitles[slug]&&links[pageTitles[slug]])a.href=links[pageTitles[slug]];});
  }).catch(function(){});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
})();
//

//

(function() {
 function htmlEl(tag,classes){var el=document.createElement(tag);if(classes)el.className=classes;return el;}
 function render(raw,title){
  var wrapper=htmlEl('div');wrapper.innerHTML=raw||'';
  var existing=wrapper.querySelector('article.article');
  var root=document.getElementById('lokhit-native')||document.getElementById('lokhit-article-fallback');
  if(!root)return;
  var parent=htmlEl('div','container');
  var crumbs=wrapper.querySelector('.breadcrumbs');
  if(crumbs)parent.appendChild(crumbs);
  var layout=htmlEl('div','content-layout');
  if(existing){
   var origLayout=existing.closest('.content-layout');
   var aside=origLayout&&origLayout.querySelector('aside');
   layout.appendChild(existing);
   if(aside)layout.appendChild(aside);
  }else{
   var article=htmlEl('article','article');
   var h1=htmlEl('h1');h1.textContent=title||document.title;article.appendChild(h1);
   var body=htmlEl('div','article-body');body.innerHTML=raw||'';article.appendChild(body);
   layout.appendChild(article);
  }
  parent.appendChild(layout);root.replaceChildren(parent);
  var native=document.getElementById('lokhit-blog-content');
  if(native&&native.contains(root)&&root.id==='lokhit-article-fallback'){
    var w=document.getElementById('lokhit-native');if(w)w.style.display='none';
  }
 }
 function isArticlePath(){return /^\/[0-9]{4}\/[0-9]{2}\/[^/]+\.html$/.test(location.pathname);}
 function run(){
  if(!isArticlePath())return;
  var rendered=document.querySelector('#lokhit-native .blogger-post-original');
  if(rendered&&rendered.innerHTML.trim()){render(rendered.innerHTML,document.title);return;}
  fetch('/feeds/posts/default?alt=json&max-results=150').then(function(r){if(!r.ok)throw Error('News feed unavailable');return r.json();}).then(function(data){
    var entries=(data.feed&&data.feed.entry)||[];
    var match=entries.find(function(e){return (e.link||[]).some(function(a){if(a.rel!=='alternate')return false;try{return new URL(a.href).pathname===location.pathname;}catch(err){return false;}});});
    if(!match){return;}
    render(match.content&&match.content.$t||'',match.title&&match.title.$t||'');
  }).catch(function(e){console.error('Lokhit article fallback',e);});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
})();
//
